     2	 * ЕДИНЫЙ КОНФИГ цифрового двойника карьера Актогай.
     3	 *
     4	 * Модель построена по мотивам открытых данных о медном месторождении Актогай (Восточный Казахстан).
     5	 * ВСЕ числовые значения ниже — ОЦЕНКА, сверить с открытыми источниками (годовые отчёты KAZ Minerals).
     6	 * Операционные данные (поломки, очереди, расход) смоделированы и не являются данными предприятия.
     7	 *
     8	 * Моделируется не весь карьер, а «сегмент» парка: 10–30 самосвалов и 5 экскаваторов,
     9	 * поэтому план смены и производительность фабрики масштабированы под этот сегмент.
    10	 */
    11	import type { Material } from './types';
    12	
    13	export interface ExcavatorSpec {
    14	  name: string;
    15	  material: Material;
    16	  /** Производительность погрузки, т/мин. */
    17	  rateTpm: number;
    18	  /** Среднее содержание меди в забое, % (0 — вскрыша). Оценка. */
    19	  gradePct: number;
    20	  /** Индекс кольцевой дороги-бермы (1 — верхняя, 3 — дно карьера). */
    21	  ring: number;
    22	  /** Угол расположения забоя на берме, градусы (0 — восток, 90 — юг на экране). */
    23	  angleDeg: number;
    24	  /** Выработка (индекс в SimConfig.pits): 0 — главный карьер. */
    25	  pit?: number;
    26	}
    27	
    28	/** Выработка: чаша с уступами, своими спиральными съездами и кольцевыми бермами. */
    29	export interface PitSpec {
    30	  name: string;
    31	  /** Центр и поворот длинной оси в координатах модели, м и градусы. */
    32	  cx: number;
    33	  cy: number;
    34	  rotDeg: number;
    35	  /** Полуоси по бровке, м. */
    36	  semiMajorM: number;
    37	  semiMinorM: number;
    38	  /** Глубина, м, и число уступов (по 15 м). */
    39	  depthM: number;
    40	  benchCount: number;
    41	  /** Масштаб дна относительно бровки. */
    42	  bottomScale: number;
    43	  /** Витков спирального съезда от бровки до дна, узлов на съезде. */
    44	  rampTurns: number;
    45	  rampNodes: number;
    46	  /** Уровни кольцевых берм в долях глубины (0 — бровка, 1 — дно); должны попадать в узлы съезда. */
    47	  ringLevels: number[];
    48	  /** Узлов на кольце (кратно числу съездов). */
    49	  ringNodes: number;
    50	  /** Съезды: начальные углы (равномерно по кругу) и названия. */
